import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.CZrxoOIU.js";const p=JSON.parse('{"title":"Scope and Priority of Attributes","description":"","frontmatter":{},"headers":[],"relativePath":"en/old/basic/attribute-scope-features.md","filePath":"en/old/basic/attribute-scope-features.md","lastUpdated":1719119907000}'),o={name:"en/old/basic/attribute-scope-features.md"};function s(d,e,l,n,h,c){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="scope-and-priority-of-attributes" tabindex="-1">Scope and Priority of Attributes <a class="header-anchor" href="#scope-and-priority-of-attributes" aria-label="Permalink to &quot;Scope and Priority of Attributes&quot;">​</a></h1><h2 id="scope-of-attributes" tabindex="-1">Scope of Attributes <a class="header-anchor" href="#scope-of-attributes" aria-label="Permalink to &quot;Scope of Attributes&quot;">​</a></h2><p>Some attributes, such as <code>[Header]</code>, can be applied to interfaces, methods, and parameters, with slightly different meanings and results depending on where they are used:</p><p>When applied to an interface, it means that all methods under the interface will have this request header added before the request is made. When applied to a method, it means that this method will have this request header added before the request is made. When applied to a parameter, it means that the value of the parameter will be used as the value of the request header, which can be dynamically passed in by the caller.</p><h2 id="priority-of-attributes" tabindex="-1">Priority of Attributes <a class="header-anchor" href="#priority-of-attributes" aria-label="Permalink to &quot;Priority of Attributes&quot;">​</a></h2><p>Method-level attributes have higher priority than interface-level attributes. When <code>AllowMultiple</code> is set to <code>true</code>, both method-level and interface-level attributes take effect. When <code>AllowMultiple</code> is set to <code>false</code>, only the method-level attribute takes effect, and the interface-level attribute is ignored.</p>',6)])])}const f=t(o,[["render",s]]);export{p as __pageData,f as default};
